#!/usr/bin/env python3
"""
Round 100b (culprits), 28 September 2026. Round 99b must be applied first.

Skin and fur farms their own heading; the food industry's owners under Meat;
zoos off the registered facilities; point rows coloured by their amounts;
heights raised, country rows raised by their figures, point rows raised where
they crowd; public money behind the harm (World Bank, IMF) in place of the
Subsidising Extinction page; free-flowing rivers and fish by basin; the farm
fields counted wider out; the hologram's blue shading switchable.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ""
NOTE = '## Round 100b (28 September)\n\nNeeds round 99b (runs after it by name). Tiles patch round100b_tiles.py beside it.\n\n- Menu: Animal skin and fur farms is its own h3 (after Meat and agriculture);\n  Meat ends with The culprits (site_food_system) and Meat grown from cells\n  (cultivated_meat_laws, retitled "... as an alternative to slaughter ...").\n- Biodiversity > Wildlife and timber crime: goc_flora, goc_fauna in place of\n  the Power BI page. pe_subsidising (page) replaced by bundle publicharm:\n  wb_harm_projects (World Bank Category A / High risk projects at their own\n  locations, colourBy commitment) and imf_fossil_subsidies (IMF via Data360,\n  country, % of GDP) from tiles public_harm.py.\n- abattoir_facilities: zoos not marked as slaughtering filtered (where on\n  x_activities); title without zoos.\n- colourBy on bocc, largest_companies, largest_banks, development_banks,\n  pe_banks, haz_ncei_quakes, haz_eruptions, haz_tsunamis; amountWords says\n  billion/trillion and keeps a decimal under 100.\n- Heights: RELIEF_BOOST 3 (world view, easing to the old lift by zoom 5);\n  country rows get a fill-extrusion ${id}-lift by the same scale as their\n  colour (LIFT_TOP 800 km at z0), "Raise figures as heights" in the View box\n  (LIFT_ON, setLift); point rows (sitemap and geojsonlive, 30+ points) get a\n  chip "Raise where the points crowd" (POINT_RELIEFS, 0.25 degree grid,\n  smoothed, through the relief:// protocol).\n- Fish: fish_rivers (Grill et al. 2019 free-flowing rivers, rasterlive from\n  tiles fish_rivers.py) and fish_basins (Tedesco et al. 2017, pmchoose numbers\n  native / introduced / endemic, tiles fish_basins.py).\n- ftw_fields: overview raster wider out (tiles ftw_overview.py: fields per\n  100 km2 per one-degree square from the download tiles\' parquet footers).\n- Hologram: "Blue shading" option (opt.shade, body.holo-noshade).\n- Script version app.js?v=991 (older tests match a two-digit prefix).\n\n'
HEAD = "## Round 100b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round100b: run from the culprits repository root")
    if "## Round 99b" not in (root / "HANDOFF.md").read_text(encoding="utf-8"):
        sys.exit("round100b: round 99b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round100b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round100b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round100b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 99b")
        h.write_text(text[:at] + NOTE + "\n" + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
